def minima(produits):
    mini = {}
    for p in produits:
        cat = p["categorie"]
        if cat not in mini:
            mini[cat] = p["prix"]        # première fois qu'on voit cette catégorie
        elif p["prix"] < mini[cat]:
            mini[cat] = p["prix"]        # on a trouvé moins cher
    return mini


