exercices.correction:
# 1. NSI : 234 % 5 = 4 ; BAC : 198 % 5 = 3 ; AMI : 215 % 5 = 0 ; NSI : déjà en case 4, ignoré ;
#    CAB : 198 % 5 = 3, collision avec BAC, on l'ajoute dans la même case.
#    Table : [["AMI"], [], [], ["BAC", "CAB"], ["NSI"]]

def creer_table(taille):
    return [[] for i in range(taille)]


def hachage(mot, taille):
    somme = 0
    for lettre in mot:
        somme = somme + ord(lettre)
    return somme % taille


# 2.
def ajouter_sans_doublon(table, mot):
    case = table[hachage(mot, len(table))]
    if mot in case:
        return False          # déjà présent : on ne l'ajoute pas
    case.append(mot)
    return True


# 3.
def ranger(mots, taille):
    table = creer_table(taille)
    for mot in mots:
        ajouter_sans_doublon(table, mot)
    return table

# 4. Un même mot a toujours le même haché : s'il est déjà rangé, il est forcément
#    dans la case de son haché. Inutile de regarder les autres cases.

