def puissance(x, n):
    if n == 0:
        return 1                        # cas de base
    return x * puissance(x, n - 1)      # n diminue à chaque appel


def nb_chiffres(n):
    if n < 10:
        return 1                        # cas de base : un seul chiffre
    return 1 + nb_chiffres(n // 10)     # on enlève le dernier chiffre

