def dicho_rec(liste, x, debut, fin):
    if debut >= fin:              # zone vide : x n'est pas là
        return -1
    milieu = (debut + fin) // 2
    if liste[milieu] == x:
        return milieu
    elif liste[milieu] < x:
        return dicho_rec(liste, x, milieu + 1, fin)    # à droite
    else:
        return dicho_rec(liste, x, debut, milieu)      # à gauche (fin exclue)


# 2. Le premier appel couvre toute la liste : debut = 0 et fin = len(liste).
def recherche(liste, x):
    return dicho_rec(liste, x, 0, len(liste))
